def longestSubstring(s, k):
    if len(s) < k:
        return 0

    # Count the frequency of each character in the string
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1

    # If all characters appear at least k times, the whole string is valid
    if all(v >= k for v in count.values()):
        return len(s)

    # Find the first character that appears less than k times
    for i, char in enumerate(s):
        if count[char] < k:
            # Split the string by this character and recursively find the longest valid substring
            return max(longestSubstring(s[:i], k), longestSubstring(s[i+1:], k))

    # If no such character is found, the whole string is valid
    return len(s)
